SourceCode.Declaration:
/// <summary>
/// Data contract of one runtime task (a bundle of items, or the summary task) of the mass trade agreement price update.
/// </summary>
[DataContractAttribute]
public class DYLO_TradeAgreementPriceAdjTaskContract
{
    DYLO_PriceAdjRunId          runId;
    PriceDiscJournalNum         journalNum;
    List                        itemIds;
    LineNum                     lineNumBase;
    PriceGroupId                custPriceGroup;
    DYLO_PriceAdjPercent        adjustmentPct;
    TransDate                   effectiveFromDate;
    DYLO_PriceAdjRoundingRule   roundingRule;
    NoYes                       autoPost;
    int                         bundleCount;
}

Method.Source:
[DataMemberAttribute('RunId')]
public DYLO_PriceAdjRunId parmRunId(DYLO_PriceAdjRunId _runId = runId)
{
    runId = _runId;
    return runId;
}

[DataMemberAttribute('JournalNum')]
public PriceDiscJournalNum parmJournalNum(PriceDiscJournalNum _journalNum = journalNum)
{
    journalNum = _journalNum;
    return journalNum;
}

[
    DataMemberAttribute('ItemIds'),
    AifCollectionTypeAttribute('return', Types::String)
]
public List parmItemIds(List _itemIds = itemIds)
{
    itemIds = _itemIds;
    return itemIds;
}

[DataMemberAttribute('LineNumBase')]
public LineNum parmLineNumBase(LineNum _lineNumBase = lineNumBase)
{
    lineNumBase = _lineNumBase;
    return lineNumBase;
}

[DataMemberAttribute('CustPriceGroup')]
public PriceGroupId parmCustPriceGroup(PriceGroupId _custPriceGroup = custPriceGroup)
{
    custPriceGroup = _custPriceGroup;
    return custPriceGroup;
}

[DataMemberAttribute('AdjustmentPct')]
public DYLO_PriceAdjPercent parmAdjustmentPct(DYLO_PriceAdjPercent _adjustmentPct = adjustmentPct)
{
    adjustmentPct = _adjustmentPct;
    return adjustmentPct;
}

[DataMemberAttribute('EffectiveFromDate')]
public TransDate parmEffectiveFromDate(TransDate _effectiveFromDate = effectiveFromDate)
{
    effectiveFromDate = _effectiveFromDate;
    return effectiveFromDate;
}

[DataMemberAttribute('RoundingRule')]
public DYLO_PriceAdjRoundingRule parmRoundingRule(DYLO_PriceAdjRoundingRule _roundingRule = roundingRule)
{
    roundingRule = _roundingRule;
    return roundingRule;
}

[DataMemberAttribute('AutoPost')]
public NoYes parmAutoPost(NoYes _autoPost = autoPost)
{
    autoPost = _autoPost;
    return autoPost;
}

[DataMemberAttribute('BundleCount')]
public int parmBundleCount(int _bundleCount = bundleCount)
{
    bundleCount = _bundleCount;
    return bundleCount;
}
